import SwiftUI

/// Uygulama dili: Otomatik (telefon Türkçeyse Türkçe, değilse İngilizce), Türkçe ya da English.
enum AppLang {
    static var pref: String { UserDefaults.standard.string(forKey: "lang") ?? "auto" }
    static var isEnglish: Bool {
        switch pref {
        case "tr": return false
        case "en": return true
        default: return !(Locale.preferredLanguages.first ?? "tr").hasPrefix("tr")
        }
    }
}

/// Metin çevirisi: Türkçe asıl metindir; İngilizce seçiliyse sözlükten gelir, yoksa Türkçe kalır.
func L(_ s: String) -> String { AppLang.isEnglish ? (enStrings[s] ?? s) : s }
/// Biçimli metin: L("Sinyal iyi · ±%d m") gibi, ardından değerler
func LF(_ s: String, _ args: CVarArg...) -> String { String(format: L(s), arguments: args) }

